-- Security audit 2026-10-25, fingerprint
-- rls-inventory-items-branch-inventory-insert-no-role-check (medium):
-- inventory_items_tenant_insert/_update and branch_inventory_tenant_insert/
-- _update (generated by the generic tenant_tables loop in
-- 20240601000000_track_base_schema.sql) only ever checked
-- tenant_id = app_current_tenant_id(), with no role predicate. The app's UI
-- hides the bulk-import button unless hasPermission("inventory.create") is
-- true (cashier/tailor lack it), but InventoryManager.tsx's
-- handleConfirmImport writes directly to these two tables from the browser
-- with no server route, so any staff member of the tenant -- including a
-- cashier -- could bypass that UI-only gate via a direct Supabase client
-- call. Same pattern, same fix shape as customers_tenant_delete
-- (20260917150000_customers_delete_role_guard.sql).
--
-- Restricted to the roles permissionService.ts's DEFAULT_ROLES actually
-- grants inventory.create/inventory.manage: owner, admin, manager,
-- branch_manager, warehouse_manager.
--
-- UPDATE is included here (unlike the customers precedent, which scoped
-- itself to DELETE only) because InventoryManager.tsx's manual stock
-- adjustment and bulk import both perform direct UPDATEs to these same two
-- tables for the same inventory.create/manage-gated actions -- there is no
-- separate, lower-privilege UPDATE use case on these tables analogous to a
-- cashier editing their own customer's measurements.

DROP POLICY IF EXISTS inventory_items_tenant_insert ON inventory_items;
CREATE POLICY inventory_items_tenant_insert ON inventory_items
    FOR INSERT WITH CHECK (
        app_is_super_admin()
        OR (
            tenant_id = app_current_tenant_id()
            AND EXISTS (
                SELECT 1 FROM staff s
                WHERE s.uid = app_current_uid()
                  AND s.status = 'active'
                  AND s.tenant_id = inventory_items.tenant_id
                  AND s.role IN ('owner', 'admin', 'manager', 'branch_manager', 'warehouse_manager')
            )
        )
    );

DROP POLICY IF EXISTS inventory_items_tenant_update ON inventory_items;
CREATE POLICY inventory_items_tenant_update ON inventory_items
    FOR UPDATE USING (
        app_is_super_admin()
        OR (
            tenant_id = app_current_tenant_id()
            AND EXISTS (
                SELECT 1 FROM staff s
                WHERE s.uid = app_current_uid()
                  AND s.status = 'active'
                  AND s.tenant_id = inventory_items.tenant_id
                  AND s.role IN ('owner', 'admin', 'manager', 'branch_manager', 'warehouse_manager')
            )
        )
    )
    WITH CHECK (
        app_is_super_admin()
        OR (
            tenant_id = app_current_tenant_id()
            AND EXISTS (
                SELECT 1 FROM staff s
                WHERE s.uid = app_current_uid()
                  AND s.status = 'active'
                  AND s.tenant_id = inventory_items.tenant_id
                  AND s.role IN ('owner', 'admin', 'manager', 'branch_manager', 'warehouse_manager')
            )
        )
    );

